escapes:
{
	var slashes = ~/^(https?://)?([a-z.]+)$/;
	var controls = ~/[
	]+/g;
	var kept = ~/\d+\.\w*\$/;
	return controls.replace(slashes.replace(text, "$2"), " ") + (kept.match(text) ? "!" : "");
}

literals:
{
	var plain = ~/[0-9]+/;
	var flagged = ~/ab+c/gi;
	return plain.match(text) || flagged.match(text);
}
